async getCustomerIdByEmail(email) {
    await this._searchRateLimitBucket.throttle();
    try {
        const result = await this._stripe.customers.search({
            query: `email:"${email}"`,
            limit: 10,
            expand: ['data.subscriptions']
        });
        const customers = result.data;

        if (customers.length === 0) {
            return null;
        }

        if (customers.length === 1) {
            return customers[0].id;
        }

        return this._findCustomerWithLatestSubscription(customers);
    } catch (err) {
        debug(`getCustomerByEmail(${email}) -> ${err.type}:${err.message}`);
        return null;
    }
}

/**
 * Finds the customer with the most recent active subscription from a list of customers.
 *
 * @param {Array<import('stripe').Stripe.Customer>} customers
 * @returns {string|null} Customer ID with the latest subscription
 */
_findCustomerWithLatestSubscription(customers) {
    let latestCustomer = null;
    let latestSubscriptionTime = 0;

    for (const customer of customers) {
        const subscription = this._getMostRecentSubscription(customer);
        if (!subscription) {
            continue;
        }

        const subscriptionTime = subscription.current_period_end || 0;
        if (subscriptionTime > latestSubscriptionTime) {
            latestSubscriptionTime = subscriptionTime;
            latestCustomer = customer;
        }
    }

    return latestCustomer ? latestCustomer.id : null;
}

/**
 * Gets the most recent subscription from a customer, if any.
 *
 * @param {import('stripe').Stripe.Customer} customer
 * @returns {import('stripe').Stripe.Subscription|null}
 */
_getMostRecentSubscription(customer) {
    if (!customer.subscriptions?.data?.length) {
        return null;
    }

    return customer.subscriptions.data.reduce((latest, subscription) => {
        const currentEnd = subscription.current_period_end || 0;
        const latestEnd = latest?.current_period_end || 0;
        return currentEnd > latestEnd ? subscription : latest;
    }, null);
}

const getCustomerByMostRecentSubscription = function (customers) {
    /**
     * Finds the customer with the most recent subscription from a list of customers.
     * @param {Array} customers - Array of customer objects with subscriptions
     * @returns {string|null} ID of the customer with the most recent subscription, or null if none found
     */
    let latestCustomer = null;
    let latestSubscriptionTime = 0;

    for (const customer of customers) {
        // skip customers with no subscriptions
        if (!customer.subscriptions?.data?.length) {
            continue;
        }

        // find the customer with the most recent subscription
        for (const subscription of customer.subscriptions.data) {
            if (subscription.current_period_end && subscription.current_period_end > latestSubscriptionTime) {
                latestSubscriptionTime = subscription.current_period_end;
                latestCustomer = customer;
            }
        }
    }

    return latestCustomer ? latestCustomer.id : null;
};

const findCustomerById = function (customers) {
    /**
     * Finds a single customer from the list.
     * @param {Array} customers - Array of customer objects
     * @returns {string|null} ID of the first customer, or null if empty
     */
    return customers.length > 0 ? customers[0].id : null;
};

/**
 * Finds or creates a Stripe Customer for a Member.
 *
 * @deprecated
 * @param {any} member
 *
 * @returns {Promise<ICustomer>}
 */
async getCustomerForMemberCheckoutSession(member) {
    await member.related('stripeCustomers').fetch();
    const customers = member.related('stripeCustomers');
    for (const data of customers.models) {
        try {
            const customer = await this.getCustomer(data.get('customer_id'));
            if (!customer.deleted) {
                return /** @type {ICustomer} */(customer);
            }
        } catch (err) {
            debug(`Ignoring Error getting customer for member ${err.message}`);
        }
    }

    debug(`Creating customer for member ${member.get('email')}`);
    const customer = await this.createCustomer({
        email: member.get('email')
    });

    return customer;
}

// Refactored getCustomerIdByEmail with extracted helpers
async getCustomerIdByEmail(email) {
    await this._searchRateLimitBucket.throttle();
    try {
        const result = await this._stripe.customers.search({
            query: `email:"${email}"`,
            limit: 10,
            expand: ['data.subscriptions']
        });
        const customers = result.data;

        // No customer found, return null
        if (customers.length === 0) {
            return null;
        }

        // Return the only customer found
        if (customers.length === 1) {
            return findCustomerById(customers);
        }

        // Multiple customers found, return the one with the most recent subscription
        return getCustomerByMostRecentSubscription(customers);
    } catch (err) {
        debug(`getCustomerByEmail(${email}) -> ${err.type}:${err.message}`);
        return null;
    }
}

