			// Clear cache for firstNode and count calls
			cache.delete(firstNode);
			let computeCount = 0;
			const original =
				sourceCodeInstance.scopeManager.scopes[0].set.get("Math")
					.references.some;
			sourceCodeInstance.scopeManager.scopes[0].set.get(
				"Math",
