			 globalScope.set.get("Foo"),
		 );
		 assert.strictEqual(
			 globalScope.references[1].resolved,
			 globalScope.set.get("Bar"),
		 );
		 assert.strictEqual(
			 globalScope.references[2].resolved,
			 globalScope.set.get("Baz"),
