/**
 * Get variables in the current scope
 * @param {Object} scope current scope
 * @param {string} name name of the variable to look for
 * @returns {ASTNode|null} The variable object
 * @private
 */
function getVariable(scope, name) {
	return scope.variables.find(v => v.name === name) || null;
}

//------------------------------------------------------------------------------
// Helper functions for type-specific processing (replaces conditional dispatch)
//------------------------------------------------------------------------------

/**
 * Apply settings for global variable with explicit "readonly" attribute.
 * @param {Object} variable The variable to configure.
 * @returns {void}
 */
function applyReadonlyGlobal(variable) {
	variable.eslintImplicitGlobalSetting = "readonly";
	variable.writeable = false;
}

/**
 * Apply settings for global variable with explicit "writable" attribute.
 * @param {Object} variable The variable to configure.
 * @returns {void}
 */
function applyWritableGlobal(variable) {
	variable.eslintImplicitGlobalSetting = "writable";
	variable.writeable = true;
}

/**
 * Apply default ES global attribute to a variable.
 * @param {Object} variable The variable to configure.
 * @param {Object} esGlobals The ES globals map.
 * @returns {void}
 */
function applyDefaultESSetting(variable, esGlobals) {
	const isWritable = esGlobals[variable.name];
	variable.eslintImplicitGlobalSetting = isWritable ? "writable" : "readonly";
	variable.writeable = isWritable;
}

/**
 * Process a custom global declared only in inline comments.
 * @param {Object} variable The variable to configure.
 * @param {Object} attrs Inline comment attributes.
 * @returns {void}
 */
function applyInlineOnlyGlobal(variable, attrs) {
	variable.eslintExplicitGlobal = true;
	variable.eslintExplicitGlobalComments = attrs.comments;
	variable.writeable = attrs.writeable;
	variable.eslintImplicitGlobalSetting = void 0;
}

/**
 * Process a custom global declared only in config.
 * @param {Object} variable The variable to configure.
 * @param {string} setting injection setting.
 * @returns {void}
 */
function applyConfigOnlyGlobal(variable, setting) {
	variable.eslintExplicitGlobal = false;
	variable.eslintExplicitGlobalComments = void 0;
	variable.writeable = setting === "writable";
	variable.eslintImplicitGlobalSetting = "writable";
}

/**
 * Process a global variable with both config and inline declarations.
 * Adjusts attributes based on precedence rules.
 * @param {Object} variable The variable to configure.
 * @param {Object} configAttr Config attributes.
 * @param {Object} inlineAttr Inline attributes.
 * @returns {void}
 */
function applyConfigAndInlineGlobal(variable, configAttr, inlineAttr) {
	variable.eslintExplicitGlobal = true;
	variable.eslintExplicitGlobalComments = inlineAttr.comments;
	variable.writeable = inlineAttr.writeableFromInline;
	variable.eslintImplicitGlobalSetting = configAttr.setting;
}

/**
 * Process a global variable declared in code but not explicitly configured.
 * @param {Object} variable The variable to configure.
 * @returns {void}
 */
function applyInCodeOnlyGlobal(variable) {
	variable.eslintExplicitGlobal = false;
	variable.eslintExplicitGlobalComments = void 0;
	variable.writeable = void 0;
	variable.eslintImplicitGlobalSetting = void 0;
}

/**
 * Generic handler for global variable finalization.
 * @param {Object} variable The variable to process.
 * @param {Object} esGlobals ES globals map.
 * @param {string|null} configSetting Config setting or null.
 * @param {Object|null} inlineAttrs Inline attributes or null.
 * @returns {void}
 */
function finalizeGlobalVariable(variable, esGlobals, configSetting, inlineAttrs) {
	if (configSetting && inlineAttrs) {
		applyConfigAndInlineGlobal(variable, { setting: configSetting }, inlineAttrs);
	} else if (configSetting) {
		applyConfigOnlyGlobal(variable, configSetting);
	} else if (inlineAttrs) {
		applyInlineOnlyGlobal(variable, inlineAttrs);
	} else if (!esGlobals[variable.name]) {
		applyInCodeOnlyGlobal(variable);
	} else {
		applyDefaultESSetting(variable, esGlobals);
	}
}

