										const blockStatement =
											functionDecl.body;

										// Function parameter references
										const paramRef =
											blockStatement.body[0].expression;
										const NaNRef =
											blockStatement.body[1].expression;

										assert.strictEqual(
											paramRef.name,
											"param",
										);
										assert.strictEqual(NaNRef.name, "NaN");

										assert.isFalse(
											sourceCode.isGlobalReference(
												paramRef,
