		it("should respect /*globals*/ directive comments", () => {
			const code =
				"/*globals customGlobal:writable, String:off */ customGlobal; String;";
			let spy;

			const config = {
				plugins: {
					test: {
						rules: {
							checker: {
								create(context) {
