				const scopeManager = eslintScope.analyze(ast, {
					ignoreEval: true,
					ecmaVersion: 6,
				});
				const sourceCode = new SourceCode({
					text: code,
					ast,
					scopeManager,
				});

				sourceCode.applyInlineConfig();
				sourceCode.finalize();

				const globalScope = sourceCode.scopeManager.scopes[0].set;

				return globalScope;
			}

