			assert.strictEqual(
				sourceCode.getIndexFromLoc({ line: 1, column: 3 }),
				3,
			);
			assert.strictEqual(
				sourceCode.getIndexFromLoc({ line: 2, column: 0 }),
				4,
			);
			assert.strictEqual(
				sourceCode.getIndexFromLoc({ line: 7, column: 0 }),
