			);
		});

		it("should throw a useful error if given a malformed location", () => {
			assert.throws(
				() => sourceCode.getIndexFromLoc(5),
				/Expected `loc` to be an object with numeric `line` and `column` properties\./u,
			);

			assert.throws(
				() => sourceCode.getIndexFromLoc(null),
				/Expected `loc` to be an object with numeric `line` and `column` properties\./u,
			);

			assert.throws(
