Query.prototype.setOptions = function(options, overwrite) {
  // overwrite is only for internal use
  if (overwrite) {
    // ensure that _mongooseOptions & options are two different objects
    this._mongooseOptions = (options && utils.clone(options)) || {};
    this.options = options || {};

    if ('populate' in options) {
      this.populate(this._mongooseOptions);
    }
    return this;
  }
  if (options == null) {
    return this;
  }
  if (typeof options !== 'object') {
    throw new Error('Options must be an object, got "' + options + '"');
  }

  if (Array.isArray(options.populate)) {
    const populate = options.populate;
    delete options.populate;
    const _numPopulate = populate.length;
    for (let i = 0; i < _numPopulate; ++i) {
      this.populate(populate[i]);
    }
  }

  const optionsKeys = Object.keys(options);
  for (const key of optionsKeys) {
    switch (key) {
      case 'useFindAndModify':
        this._mongooseOptions.useFindAndModify = options[key];
        delete options[key];
        break;
      case 'omitUndefined':
        this._mongooseOptions.omitUndefined = options[key];
        delete options[key];
        break;
      case 'setDefaultsOnInsert':
        this._mongooseOptions.setDefaultsOnInsert = options[key];
        delete options[key];
        break;
      case 'overwriteDiscriminatorKey':
        this._mongooseOptions.overwriteDiscriminatorKey = options[key];
        delete options[key];
        break;
      case 'sanitizeProjection':
        if (options[key] && !this._mongooseOptions.sanitizeProjection) {
          sanitizeProjection(this._fields);
        }
        this._mongooseOptions.sanitizeProjection = options[key];
        delete options[key];
        break;
      case 'defaults':
        this._mongooseOptions.defaults = options[key];
        break;
      default:
        // For any other keys, delegate to mquery's setOptions
        break;
    }
  }

  return Query.base.setOptions.call(this, options);
};
